package com.example.takura.shared.web;
import io.micrometer.core.instrument.*;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.util.concurrent.TimeUnit;import org.slf4j.*;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import org.springframework.web.servlet.HandlerMapping;
@Component public final class RequestTelemetryFilter extends OncePerRequestFilter{private static final Logger log=LoggerFactory.getLogger(RequestTelemetryFilter.class);private final MeterRegistry metrics;public RequestTelemetryFilter(MeterRegistry m){metrics=m;}@Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{long start=System.nanoTime();Throwable error=null;try{chain.doFilter(req,res);}catch(Throwable t){error=t;throw t;}finally{String route=String.valueOf(req.getAttribute(HandlerMapping.BEST_MATCHING_PATTERN_ATTRIBUTE));if(route==null||"null".equals(route))route="UNMATCHED";String status=Integer.toString(res.getStatus());long duration=System.nanoTime()-start;Timer.builder("takura.http.server.duration").tag("route",route).tag("method",req.getMethod()).tag("status",status).register(metrics).record(duration,TimeUnit.NANOSECONDS);if(error!=null||res.getStatus()>=500)metrics.counter("takura.http.server.errors","route",route,"status",status).increment();log.info("http_request route={} status={} duration_ms={} service=takura-backend",route,status,TimeUnit.NANOSECONDS.toMillis(duration));}}}
